// Package static embeds the built tracker script (generated by `npm run build` in /tracker).
package static

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"net/http"
)

//go:embed t.js
var trackerJS []byte

var trackerETag = func() string {
	sum := sha256.Sum256(trackerJS)
	return `"` + hex.EncodeToString(sum[:8]) + `"`
}()

// TrackerHandler serves t.js with caching headers.
func TrackerHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	w.Header().Set("Cache-Control", "public, max-age=3600")
	w.Header().Set("ETag", trackerETag)
	w.Header().Set("Access-Control-Allow-Origin", "*")
	if r.Header.Get("If-None-Match") == trackerETag {
		w.WriteHeader(http.StatusNotModified)
		return
	}
	w.Write(trackerJS)
}
